insert into public.ddrive_city_scores (hazard_event, hazard_family, exposure_infrastructure, exposure_productive, exposure_essential, exposure_human, vulnerability_rating, response_measures, likelihood, severity, evidence_anchor, validation_status) values
  ('Riverine & flash flood', 'H2 Hydrological', '9-Extremely likely', '9-Extremely likely', '9-Extremely likely', '9-Extremely likely', 90, '4-Some measures in place', 9, 50, 'Largest modelled exposure (₱222.4B); Pagsangaan/Anilao/Malbasag system; flood events almost yearly (Jolina/Odette/Agaton/Paeng 2021–22); degrading flood controls', 'Desk score — pending QRE workshop validation'),
  ('Rain-induced landslide', 'H2 Hydrological', '8-Very likely', '7-Likely', '7-Likely', '8-Very likely', 75, '3-Few measures in place', 7, 40, '₱205.5B modelled exposure; 70% of city highly susceptible (MGB); slopes fail most rainy seasons; road-cut slopes worsen risk', 'Desk score — pending QRE workshop validation'),
  ('Storm surge / wave action', 'H2 Hydrological', '8-Very likely', '7-Likely', '7-Likely', '8-Very likely', 75, '4-Some measures in place', 6, 20, '15 coastal barangays; ₱33.3B modelled; ~10-yr recurrence; mangrove restoration underway on 6 sites', 'Desk score — pending QRE workshop validation'),
  ('Tropical cyclone (severe wind)', 'H3 Meteorological', '8-Very likely', '9-Extremely likely', '8-Very likely', '9-Extremely likely', 85, '5-Reasonable measures in place', 8, 30, 'Yolanda 2013 damaged 55,589 houses; wind 117–220 km/h (20-/500-yr); ~annual typhoon passage', 'Desk score — pending QRE workshop validation'),
  ('Earthquake (ground shaking)', 'H1 Geophysical', '8-Very likely', '8-Very likely', '9-Extremely likely', '9-Extremely likely', 85, '3-Few measures in place', 5, 20, 'PEIS VIII+ citywide (2026); M6.5 in 2017 damaged 3,593 houses + 113 schools; 297 aftershocks/day', 'Desk score — pending QRE workshop validation'),
  ('Ground rupture (Philippine Fault)', 'H1 Geophysical', '6-Probable', '5-Possible', '6-Probable', '6-Probable', 58, '2-Very few measures in place', 4, 20, 'PF trace through eastern uplands past Lake Danao (READY 2009); 5-m buffer easement in zoning; no physical mitigation in upland barangays', 'Desk score — pending QRE workshop validation'),
  ('Liquefaction', 'H1 Geophysical', '7-Likely', '7-Likely', '8-Very likely', '7-Likely', 73, '2-Very few measures in place', 5, 30, '₱189.3B modelled; high zone covers waterfront, western lowland, south coast incl. Danhug EC site', 'Desk score — pending QRE workshop validation'),
  ('Tsunami', 'H2 Hydrological', '7-Likely', '6-Probable', '7-Likely', '8-Very likely', 70, '1-Extremely few measures in place', 2, 10, '₱59.0B modelled; 1–<3 m inundation western lowland + Camp Downes–Danhug strip (PHIVOLCS 2024); no siren/vertical-evacuation infrastructure documented', 'Desk score — pending QRE workshop validation'),
  ('Urban / structural fire (post-disaster)', 'H7 Anthropogenic', '6-Probable', '6-Probable', '6-Probable', '7-Likely', 63, '4-Some measures in place', 6, 20, 'Fire following earthquake is a standing EOC concern; dense poblacion built-up (35.42 km², half at waterfront)', 'Desk score — pending QRE workshop validation'),
  ('Epidemic (post-disaster / dengue)', 'H5 Biological', '5-Possible', '5-Possible', '8-Very likely', '7-Likely', 63, '4-Some measures in place', 6, 20, 'Evacuation-center outbreaks are a recurring risk after typhoons; health facilities in hazard zones', 'Desk score — pending QRE workshop validation');
