insert into public.ddrive_sources (Source ID, Source Name, Owner / Publisher, URL, Vintage / Reference Date, Scale / Coverage, Date Accessed, Known Limitations) values
  ('S-01', 'Philippine Standard Geographic Code (PSGC) — Ormoc City barangays', 'Philippine Statistics Authority', 'https://psa.gov.ph/classification/psgc/barangays/0803738000', 'As of 31 July 2025 (85 barangays)', 'Barangay (10-digit codes); urban/rural class; 2020 Census population', '9 Nov 2026', 'Official codes and names; website shows 10 rows per page — full per-barangay 2020 table not machine-readable here; 2020 figures are on the 110-barangay configuration'),
  ('S-02', '2024 Census of Population (2024 POPCEN) — Ormoc City total and per-barangay counts', 'Philippine Statistics Authority (RSSO VIII)', 'https://rsso08.psa.gov.ph/content/highlights-2024-census-population-2024-popcen-ormoc-city', 'As of 1 July 2024; counts declared official by the President 17 July 2025', 'City and barangay level; total 238,545', '9 Nov 2026', 'Per-barangay 2024 figures cross-checked: master column sums exactly to 238,545; an earlier working note citing a 29 December 2025 release date could not be confirmed against PSA records'),
  ('S-03', '2020 Census of Population and Housing (2020 CPH) — barangay counts', 'Philippine Statistics Authority', 'https://www.philatlas.com/visayas/r08/leyte/ormoc.html', '1 May 2020; published 2021', '110-barangay configuration; city total 230,998', '9 Nov 2026', '2020 counts predate the 2022 plebiscite (Ordinance 052 s.2021); boundaries of affected barangays differ from the current 85-barangay configuration'),
  ('S-04', 'GeoRisk Philippines — Data and Methods', 'GeoRisk Philippines Initiative (DOST, PHIVOLCS, MGB and partners)', 'https://georisk.gov.ph/', 'Methodology as published (population: PSA; flood hazard: DENR-MGB 2018)', 'National; areal-proportion method', '9 Nov 2026', 'Areal-proportion estimate — not a household-level count; assumes uniform population distribution across barangay land'),
  ('S-05', 'GeoAnalyticsPH — barangay hazard/exposure analytics', 'GeoAnalyticsPH / DOST', 'https://georisk.gov.ph/geodata/', 'Reports generated 5 Nov 2026 (Alegria); Curva chart vintage not stated', 'Barangay level (approximate boundaries)', '9 Nov 2026', 'Reports state "administrative boundaries are approximate and not authoritative"; Curva chart total (3,309) differs from official 2024 count (3,323) — see QA log L-02'),
  ('S-06', 'DENR-MGB 2018 flood hazard layer; PHIVOLCS earthquake/ tsunami hazard layers', 'DENR-Mines and Geosciences Bureau; DOST-PHIVOLCS', 'https://mgb.gov.ph/ ; https://phivolcs.dost.gov.ph/', '2018 (flood); current PHIVOLCS releases', 'National hazard mapping', '9 Nov 2026', 'Authoritative within mandates; barangay-level intersection not yet performed for this workbook'),
  ('S-07', 'City of Ormoc CDRA, DRRM 10-Year Plan, CLUP 2017–2027, LCCAP', 'City Government of Ormoc (CPDO / CDRRMO)', 'City records (Google Drive corpus)', 'CLUP 2017–2027 (110-barangay baseline); CDRA mixes 85/110 references', 'City level', '9 Nov 2026', 'CDRA adopted Chapters 5–6 tables pending; CDRA climate tables labelled for another LGU (quality flag); hazard tags to be reconciled against these plans'),
  ('S-08', 'Original workbook: Ormoc-City-Barangays_PSGC-Dev-Team (Google Sheets)', 'City Government of Ormoc — Dev Team', 'https://docs.google.com/spreadsheets/d/1VhaCf--3guTixcu8ICOz3s1DdGYb7IljabT507oF7d8', 'Sheet state as of 9 Nov 2026', '85-barangay master with coordinates and hazard report tabs', '9 Nov 2026', 'Coordinate provenance mixed (city sheet vs PSA PSGC 3Q 2026 centroids); hazard columns largely unpopulated; identifiers preserved in this workbook'),
  ('S-09', 'Community Disaster Risk Assessment (CDRA), Ormoc City — Preliminary Pages', 'City Government of Ormoc / CDRRMO', 'https://drive.google.com/file/d/1odnJBB5HaWEvoU3Jo43MKE8yyV_iL_ar', 'CDRA (current update in progress)', 'Citywide', '9 Nov 2026', '6.1 MB PDF owned by cdrrmo.ormoccity@gmail.com; copy of record'),
  ('S-10', 'CDRA, Ormoc City — Chapters 1–4', 'City Government of Ormoc / CDRRMO', 'https://drive.google.com/file/d/1Wk_RFeo7Q8CUIACNxQ2UaPHUyuQ9WXrh', 'CDRA (current update in progress)', 'Citywide', '9 Nov 2026', '54.7 MB PDF; source of Tables 2–4 transcribed here'),
  ('S-11', 'Comprehensive Land Use Plan (CLUP) 2017–2027 — DHSUD Certificate of Approval', 'DHSUD / City Government of Ormoc', 'https://drive.google.com/file/d/14HF_ngbJbrYLGf4k3NCxSNHIWiPInmwb', '2017–2027 planning period', 'Citywide', '9 Nov 2026', 'For updating per user note; land-use shares cited from this CLUP'),
  ('S-12', 'CLUP Volume 2 — Zoning Ordinance (Final)', 'City Government of Ormoc', 'https://drive.google.com/file/d/13EvWRV7dbllU6QaEde9GhQJXqaeRvp45', 'CLUP 2017–2027 period', 'Citywide', '9 Nov 2026', 'Marina Fault easement already reflected in zoning'),
  ('S-13', 'Status of CLUP Approval (DHSUD)', 'DHSUD', 'https://drive.google.com/file/d/1seEP_Z4JhNg9pXlVJycKjEsWNdECgJMK', 'As of document date', 'Citywide', '9 Nov 2026', 'Approval-status record only'),
  ('S-14', 'Ormoc City DRRM 10-Year Plan (2023–2032)', 'City Government of Ormoc / CDRRMC', 'https://drive.google.com/file/d/1_TRswzfwCqwhYtlS-0ygI1PtgKYXqyof', 'SP Resolution 2023-112; CDRRMC Res. 1 s. 2023', 'Citywide', '9 Nov 2026', 'Read in full; primary source for exposure, vulnerability and capacity figures; Table 7 uses legacy 110-barangay/District scheme'),
  ('S-15', 'Local Climate Change Adaptation Plan (LCCAP) 2019–2030', 'City Government of Ormoc', 'Link invalid — file ID truncated at source (32 of 33 characters)', '2019–2030', 'Citywide', '9 Nov 2026', 'Direct read failed (entity not found); LCCAP content cited via DRRM Plan Chapter 1 (Pagsangaan River flood analysis; BCRUPD/V-LED support). Re-share valid link to register'),
  ('S-16', 'Comprehensive Development Plan (CDP) Vol. 1 — Ecological Profile', 'City Government of Ormoc', 'https://drive.google.com/file/d/1PPGKRK_faECiOA1DGj1_qYCYZtwfU39o', 'Current CDP cycle', 'Citywide', '9 Nov 2026', '8.3 MB PDF'),
  ('S-17', 'Comprehensive Development Plan (CDP) Vol. 2 — Plan Document', 'City Government of Ormoc', 'https://drive.google.com/file/d/10ucd3Bx_FBLPa7FiUqD-M4-m9yYpDvxy', 'Current CDP cycle', 'Citywide', '9 Nov 2026', '4 MB PDF'),
  ('S-18', 'CDRRMO Assessment of Org Structure, Brief Assessment, Cluster Coordinator Proposal and Hazard Inputs', 'CDRRMO Ormoc City', 'Uploaded file (docx)', 'November 2026 assessment', 'Citywide (85 barangays)', '9 Nov 2026', 'Author assessment memo; cluster proposal pending ratification'),
  ('S-19', 'CDRA Table 3 — Hazard Inventory Matrix per Barangay (images, 2 parts)', 'CDRA Ormoc', 'Uploaded files (PNG)', 'CDRA', '56 of 85 barangays (Alegria → Matica-a)', '9 Nov 2026', 'Source matrix truncated at Matica-a — remaining 29 rows not supplied; see QA L-12'),
  ('S-20', 'CDRA Table 4 — Record of Previous Disasters, Ormoc City (image)', 'CDRA Ormoc', 'Uploaded file (PNG)', 'CDRA', 'Citywide, 1991–2022', '9 Nov 2026', 'Historical event record transcribed to report and workbook'),
  ('S-21', 'CDRA Table 2 — Inventory of Hazards and Descriptions (image)', 'CDRA Ormoc', 'Uploaded file (PNG)', 'CDRA; MGB/NOAH layers', 'Citywide', '9 Nov 2026', 'Hazard inventory metadata (scale, vintage, susceptibility classes)'),
  ('S-22', 'PHIVOLCS — Ground Shaking Hazard Map, Ormoc City (v2)', 'DOST-PHIVOLCS', 'Uploaded file (PNG)', 'August 2026; 1:60,000', 'Citywide; 85-barangay boundaries', '9 Nov 2026', 'PEIS VIII+ across entire city'),
  ('S-23', 'PHIVOLCS — Tsunami Hazard Map, Ormoc City (v3)', 'DOST-PHIVOLCS', 'Uploaded file (PNG)', 'June 2024', 'Coastal barangays', '9 Nov 2026', '~2 m offshore wave height; 1 to <3 m inundation western lowland + Camp Downes–Danhug strip'),
  ('S-24', 'READY — Ground Rupture Hazard Map, Ormoc City', 'DOST-PHIVOLCS READY project', 'Uploaded file (PNG)', 'Dec 2009 / rev. Mar 2010', 'Eastern uplands', '9 Nov 2026', 'Old B-1..B-28 barangay labels; 5-m fault buffer; request current layers via GeoRiskPH'),
  ('S-25', 'READY — Liquefaction Hazard Map, Ormoc City', 'DOST-PHIVOLCS READY project', 'Uploaded file (PNG)', 'Nov 2009', 'Citywide', '9 Nov 2026', 'High along bay shore, western lowland, south coast; barangay-level class pending GIS extraction'),
  ('S-26', 'READY — Earthquake-Induced Landslide Hazard Map, Ormoc City', 'DOST-PHIVOLCS READY project', 'Uploaded file (PNG)', '2007–2010', 'Citywide', '9 Nov 2026', 'High/moderate eastern mountain belt; western plain not susceptible'),
  ('S-27', 'GeoAnalyticsPH barangay flood auto-reports (6 barangays: Alegria, Airport, Curva, Lao, Leondoni, Linao)', 'GeoAnalyticsPH / GeoRiskPH', 'Uploaded files (xlsx)', 'Generated 5–9 Nov 2026', '6 barangays', '9 Nov 2026', 'Areal-proportion model on 2020 CPH base; pending field validation'),
  ('S-28', 'Quick Risk Estimation (QRE) Tool — Ormoc City DRRMO EOC-Dev-Team adaptation (xlsm)', 'UNDRR methodology; CDRRMO EOC-Dev-Team', 'Uploaded file (xlsm); Drive copy: 1ETqwUjw9IYOoqFAIoE0R7k-pBl8_9MWp', 'UNDRR QRE; Ormoc adaptation Nov 2026', 'Citywide workshop tool', '9 Nov 2026', 'Workshop tool by design — desk scores in 14_QRE_Scoring require workshop validation; contains no custom VBA (formula + validation driven)'),
  ('S-29', 'Barangay Boundaries Repository — NAMRIA/PSGC hierarchical GeoJSON', 'bendlikeabamboo (NAMRIA v2023-11-06; PSA PSGC 2023-10-24)', 'https://github.com/bendlikeabamboo/barangay-boundaries-repository', 'Release v2026.4.13.0 (2023-10-24 snapshot); simplified tolerance 0.005°', 'National; ADM4 barangay polygons with PSGC codes', '9 Nov 2026', 'Authoritative geometry source for boundary completion; pre-dates PSGC 2026-Q1 snapshot — verify the 4 2022-poblacion barangay polygons exist (coverage 99.947%)'),
  ('S-30', 'Philippines — Subnational Administrative Boundaries (COD-AB)', 'OCHA / HDX', 'https://data.humdata.org/dataset/cod-ab-phl', 'Metadata modified 14 Aug 2026', 'National; ~1 GB geodatabase', '9 Nov 2026', 'Registered as alternate boundary source; not downloaded (size) — use if NAMRIA release lacks Ormoc features'),
  ('S-31', 'Floods_Prediction — AI-Based Flood Prediction System (demo repo)', 'ramyasree-coder', 'https://github.com/ramyasree-coder/Floods_Prediction', 'Repository HEAD (2025-era)', 'Model pattern only', '9 Nov 2026', 'Training CSV not in repo; demo-grade — Ormoc integration is blueprint-only (sheet 15)');
