-- Part 26 of 26: run after parts 1-25. Idempotent; safe to run again.
begin;

on conflict (psgc) do update set name = excluded.name, former_name = excluded.former_name, urban_rural = excluded.urban_rural, population_2024 = excluded.population_2024, population_2020 = excluded.population_2020, growth_rate_2020_2024 = excluded.growth_rate_2020_2024, households = excluded.households, density_per_ha = excluded.density_per_ha, data_quality_flag = excluded.data_quality_flag, lat = excluded.lat, lng = excluded.lng, coord_source = excluded.coord_source, coord_validation = excluded.coord_validation, cluster_no = excluded.cluster_no, cluster_label = excluded.cluster_label, district_zone = excluded.district_zone, assigned_coordinator = excluded.assigned_coordinator, cluster_validation = excluded.cluster_validation, workbook_rev = excluded.workbook_rev;


on conflict (psgc) do update set Flood Susceptibility Class = excluded.Flood Susceptibility Class, Flood Hazard Source & Vintage = excluded.Flood Hazard Source & Vintage, Flood-prone Area (ha) = excluded.Flood-prone Area (ha), Total Barangay Land Area (ha) = excluded.Total Barangay Land Area (ha), Flood-prone Land (%) = excluded.Flood-prone Land (%), Population Potentially Exposed = excluded.Population Potentially Exposed, Exposure Base Population = excluded.Exposure Base Population, Exposure Base Year = excluded.Exposure Base Year, Population Exposure (%) = excluded.Population Exposure (%), Flood Depth / Inundation Scenario = excluded.Flood Depth / Inundation Scenario, Data Confidence = excluded.Data Confidence, Validation Status = excluded.Validation Status;


on conflict (psgc) do update set Rain-Induced Landslide Susceptibility = excluded.Rain-Induced Landslide Susceptibility, Earthquake-Induced Landslide Susceptibility = excluded.Earthquake-Induced Landslide Susceptibility, Ground Shaking = excluded.Ground Shaking, Ground Rupture = excluded.Ground Rupture, Liquefaction = excluded.Liquefaction, Tsunami = excluded.Tsunami, Critical Facilities Exposed = excluded.Critical Facilities Exposed, Lifeline & Road Exposure = excluded.Lifeline & Road Exposure, Vulnerable Population Indicators = excluded.Vulnerable Population Indicators, Evacuation Access & Shelter Considerations = excluded.Evacuation Access & Shelter Considerations, Hazard Source & Vintage = excluded.Hazard Source & Vintage, Validation Status = excluded.Validation Status, Storm Surge Susceptibility = excluded.Storm Surge Susceptibility;


on conflict (psgc) do update set Population 2024 POPCEN (baseline) = excluded.Population 2024 POPCEN (baseline), Population 0–4 = excluded.Population 0–4, Population 5–17 = excluded.Population 5–17, Population 18–59 = excluded.Population 18–59, Population 60+ = excluded.Population 60+, Schools (n) = excluded.Schools (n), Health Facilities (n) = excluded.Health Facilities (n), Infrastructure & Lifelines = excluded.Infrastructure & Lifelines, Source = excluded.Source, Status = excluded.Status;


on conflict (psgc) do update set Social Sensitivity Indicators = excluded.Social Sensitivity Indicators, Access Constraints (roads, bridges, terrain) = excluded.Access Constraints (roads, bridges, terrain), Coping Capacity = excluded.Coping Capacity, Adaptive Capacity = excluded.Adaptive Capacity, Method / Source = excluded.Method / Source, Validation Status = excluded.Validation Status;


on conflict (psgc) do update set Proposed Priority Rank (1–85) = excluded.Proposed Priority Rank (1–85), Priority Basis (evidence) = excluded.Priority Basis (evidence), Population 2024 POPCEN = excluded.Population 2024 POPCEN, Assessment Confidence = excluded.Assessment Confidence, Validation Status = excluded.Validation Status;


on conflict (hazard_event) do update set hazard_family = excluded.hazard_family, exposure_infrastructure = excluded.exposure_infrastructure, exposure_productive = excluded.exposure_productive, exposure_essential = excluded.exposure_essential, exposure_human = excluded.exposure_human, vulnerability_rating = excluded.vulnerability_rating, response_measures = excluded.response_measures, likelihood = excluded.likelihood, severity = excluded.severity, evidence_anchor = excluded.evidence_anchor, validation_status = excluded.validation_status;


on conflict (ranking) do update set severity_min = excluded.severity_min, severity_max = excluded.severity_max, likelihood_min = excluded.likelihood_min, likelihood_max = excluded.likelihood_max, band = excluded.band, label = excluded.label;


on conflict (source_id) do update set Source ID = excluded.Source ID, Source Name = excluded.Source Name, Owner / Publisher = excluded.Owner / Publisher, URL = excluded.URL, Vintage / Reference Date = excluded.Vintage / Reference Date, Scale / Coverage = excluded.Scale / Coverage, Date Accessed = excluded.Date Accessed, Known Limitations = excluded.Known Limitations;


-- Expected: 85 | 85 | 85 | 85 | 85 | 85 | 10 | 25 | 31
select (select count(*) from public.ddrive_barangay_profiles) as profiles,
       (select count(*) from public.ddrive_flood)             as flood,
       (select count(*) from public.ddrive_hazards)            as hazards,
       (select count(*) from public.ddrive_exposure)         as exposure,
       (select count(*) from public.ddrive_vulnerability)    as vulnerability,
       (select count(*) from public.ddrive_priority)           as priority,
       (select count(*) from public.ddrive_city_scores)      as city_scores,
       (select count(*) from public.ddrive_risk_matrix)        as matrix,
       (select count(*) from public.ddrive_sources)            as sources;

commit;
